/**
	Returns objects related to the root Clinical Document header participant by type

	@param {Object} type - ParticipantType object element as participant type
	@return {Array} return array of participant objects
*/
function getCDAHeaderParticipant(type) {

	var result = [];

	switch (type) {

		case ParticipantType.AUTHENTICATOR: {
			for each (var auth in msg.authenticator) {
				var authenticator = getAssignedEntity(auth);
				authenticator.getParticipation().setType('AUTHEN');
				result.push(authenticator);
			}			
			break;
		}

		case ParticipantType.AUTHOR: {
			for each (var aut in msg.author) {			
				var author = new Role(aut.assignedAuthor);
				author.participation = new Participation(aut);
				author.getParticipation().setType('AUT');			
				if (aut.assignedAuthor.hasOwnProperty('assignedPerson')) {
					author.subject = new Person(aut.assignedAuthor.assignedPerson);
				}			
				if (aut.assignedAuthor.hasOwnProperty('assignedAuthoringDevice')) {
					//author.subject = new Device(aut.assignedAuthor.assignedAuthoringDevice);
				}			
				if (aut.assignedAuthor.hasOwnProperty('representedOrganization')) {
					author.scoper = new Organization(aut.assignedAuthor.representedOrganization);
				}			
				result.push(author);
			}			
			break;
		}

		case ParticipantType.CUSTODIAN: {
			var custodian = new Role(msg.custodian.assignedCustodian);
			custodian.scoper = new Organization(msg.custodian.assignedCustodian.representedCustodianOrganization);
			custodian.participation = new Participation(msg.custodian);
			custodian.getParticipation().setType('CST');
			result.push(custodian);			
			break;
		}

		case ParticipantType.DATAENTERER: {
			for each (var enterer in msg.dataEnterer) {	
				var transcriptionist = getAssignedEntity(enterer);
				transcriptionist.getParticipation().setType('ENT');
				result.push(transcriptionist);	
			}
			break;
		}

		case ParticipantType.ENCOUNTERPARTICIPANT: {
			// EncompassingEncounter participant
			break;
		}

		case ParticipantType.GUARDIAN: {
			var guardian = new Role(msg.recordTarget.patientRole.patient.guardian);
			guardian.subject = new Person(msg.recordTarget.patientRole.patient.guardian.guardianPerson);
			guardian.scoper = new Organization(msg.recordTarget.patientRole.patient.guardian.guardianOrganization);
			result.push(guardian);			
			break;
		}

		case ParticipantType.INFORMANT: {
			for each (var informantChoice in msg.informant) {			
				var informant;			
				if (informantChoice.hasOwnProperty('assignedEntity')) {			
					informant = getAssignedEntity(informantChoice);	
				} else if (informantChoice.hasOwnProperty('relatedEntity')) {			
					informant = new Role(informantChoice.relatedEntity);
					informant.subject = new Person(informantChoice.relatedEntity.relatedPerson);
					informant.participation = new Participation(informantChoice);
				}			
				if (informant.getSubject()) {
					informant.getParticipation().setType('INF');
					result.push(informant);
				}	
			}			
			break;
		}

		case ParticipantType.INFORMATIONRECIPIENT: {
			for each (var informationRecipient in msg.informationRecipient) {			
				var recipient = new Role(informationRecipient.intendedRecipient);
				recipient.subject = new Person(informationRecipient.intendedRecipient.informationRecipient);
				recipient.participation = new Participation(informationRecipient);
				recipient.scoper = new Organization(informationRecipient.intendedRecipient.receivedOrganization);
				result.push(recipient);
			}			
			break;
		}

		case ParticipantType.LEGALAUTHENTICATOR: {		
			for each (var auth in msg.legalAuthenticator) {
				var authenticator = getAssignedEntity(auth);
				authenticator.getParticipation().setType('LA');
				result.push(authenticator);
			}			
			break;
		}

		case ParticipantType.LOCATION: {
			// EncompassingEncounter location
			break;			
		}

		case ParticipantType.PARTICIPANT: {
			for each (var prt in msg.participant) {			
				var otherParticipant = new Role(prt.associatedEntity);
				otherParticipant.participation = new Participation(prt);				
				if (prt.associatedEntity.hasOwnProperty('associatedPerson')) {
					otherParticipant.subject = new Person(prt.associatedEntity.associatedPerson);
				}				
				if (prt.associatedEntity.hasOwnProperty('scopingOrganization')) {
					otherParticipant.scoper = new Organization(prt.associatedEntity.scopingOrganization);
				}			
				result.push(otherParticipant);
			}			
			break;
		}

		case ParticipantType.PERFORMER: {
			// ServiceEvent participant
			break;
		}

		case ParticipantType.PATIENT: {			
			var patient = new Patient(msg.recordTarget.patientRole);
			patient.subject = new Person(msg.recordTarget.patientRole.patient);
			patient.participation = new Participation(msg.recordTarget);
			patient.birthPlace = new Place(msg.recordTarget.patientRole.patient.birthplace.place);
			patient.scoper = new Organization(msg.recordTarget.patientRole.providerOrganization);
			result.push(patient);
			break;
		}

		case ParticipantType.RESPONSIBLEPARTY: {
			// EncompassingEncounter participant
			break;
		}
	}

	return result;	
}


/**
	Represents types of CDA participants
*/
const ParticipantType = Object.freeze({
	"AUTHENTICATOR": 0,
	"AUTHOR": 1,
	"CUSTODIAN": 2,
	"DATAENTERER": 3,
	"ENCOUNTERPARTICIPANT": 4,
	"GUARDIAN": 5,
	"INFORMANT": 6,
	"INFORMATIONRECIPIENT": 7,
	"LEGALAUTHENTICATOR": 8,
	"LOCATION": 9,
	"PARTICIPANT": 10,
	"PERFORMER": 11,
	"PATIENT": 12,
	"RESPONSIBLEPARTY": 13
});

/**
	Checks if a string is empty or populated.  If empty, returns null so DB field is null vs. ''

	@param {String} str - String to validate
	@return {String} return string
*/
function DateorNull(str) {

	try
	{
		if (str.length != 8 && str.length != 14)
		{
			logger.warn('DateorNull cant process date: ' + str + '.  String not 8 or 14 chars.  Length: ' + str.length);
			return "null";
		}
		else
		{
			if (str.length == 8)
			{
				return "'" + DateUtil.convertDate("yyyyMMdd", "yyyy-MM-dd", str).toString() + "'";
			}
			if (str.length == 14)
			{
				return "'" + DateUtil.convertDate("yyyyMMddHHmmss", "yyyy-MM-dd HH:mm:ss", str).toString() + "'";
			}
			else
			{
				logger.error('DateorNull cant process date, string not 8 or 14 chars.  Length: ' + str.length);
				return "null";	
			}
		}
	}
	catch (ex)
	{
		logger.error('Error in DateorNull Parsing String: ' + str + '.  Returning null.  Ex: ' + ex);
		return "null";
	}
}

/**
	Modify the description here. Modify the function name and parameters as needed. One function per
	template is recommended; create a new code template for each new function.

	@padchars Example '0000000000' - pad with 0's to  10 digits total
	@str your input string
	@padLeft 1 for left or 0 for right

	@return {String} return description
*/
function PadString(padchars, str, padLeft) 
{
  if (typeof str === 'undefined') 
    return padchars;
  if (padLeft) {
    return (padchars + str).slice(-padchars.length);
  } else {
    return (str + padchars).substring(0, padchars.length);
  }
}

/**
	Checks if a string is empty or populated.  If empty, returns null so DB field is null vs. ''

	@param {String} str - String to validate
	@return {String} return string
*/
function StringorNull(str) {
	if (str.length == 0)
	{
		return "null";
	}
	else
	{
		return "'" + str.replace(/\'/g,"''") + "'";
	}
}

/**
	Parse AddressParts from mailing, home or office addresses

	@param {Object} addresses - List of E4X addr elements
	@return {Array} return array of PostalAddress elements
*/
function parseAddress(addresses) {

	var addressList = [];

	for each (var address in addresses) {

		var addressPart = {};

		addressPart.nullFlavor = address.@nullFlavor.toString() || '';

		if (!addressPart.nullFlavor) {

			delete addressPart.nullFlavor;

			addressPart.use = address.@use.toString() || '';
			addressPart.city = address.city.toString() || '';
			addressPart.state = address.state.toString() || '';
			addressPart.postalCode = address.postalCode.toString() || '';
			addressPart.country = address.country.toString() || '';
			addressPart.street = [];

			for each (var line in address.streetAddressLine) {
				if (line.toString()) {
					addressPart.street.push(line.toString());
				}
			}			
		}

		addressList.push(addressPart);		
	}

	return addressList;
}

/**
	Parse a concept defined in a code system

	@param {Object} code - E4X code element 
	@return {Object} return codeType object
*/

function parseCode(code) {

/*
	Known limitations (elements not parsed):
		- originalText
		- translation
		- codingRationale
		- source
		- etc.
*/

	var codeType = {};

	codeType.nullFlavor = code.@nullFlavor.toString() || '';

	if (!codeType.nullFlavor) {

		delete codeType.nullFlavor;

		codeType.code = code.@code.toString() || '';
		codeType.codeSystem = code.@codeSystem.toString() || '';
		codeType.displayName = code.@displayName.toString() || '';
		codeType.codeSystemName = code.@codeSystemName.toString() || '';		
	}

	return (codeType.code || codeType.nullFlavor) ? codeType : null;
}

/**
	Parse the EntityName element that comprises of EntityNamePart elements

	@param {Object} names - List of E4X EntityName elements 
	@return {Array} return array of name elements
*/
function parseNames(names) {

	var nameList = [];

	for each (var entityName in names) {

		var entityNamePart = {};

		entityNamePart.nullFlavor = entityName.@nullFlavor.toString() || '';

		if (!entityNamePart.nullFlavor) {

			delete entityNamePart.nullFlavor;
			entityNamePart.use = entityName.@use.toString() || '';
			entityNamePart.family = entityName.family.toString() || '';		
			entityNamePart.given = [];
			entityNamePart.delimiter = entityName.delimiter.toString() || '';
			entityNamePart.prefix = entityName.prefix.toString() || '';
			entityNamePart.suffix = entityName.suffix.toString() || '';

			for each (var given in entityName.given) {
				if (given.toString()) {
					entityNamePart.given.push(given.toString());
				}			
			}			
		}

		nameList.push(entityNamePart);
	}

	return nameList;
}


/**
	Parse the EntityName element where EntityNamePart elements are not used (e.g., Place name)

	@param {Object} names - List of E4X EntityName elements 
	@return {Array} return array of name elements
*/
function parseEntityName(name) {

	var entityName = {};

	entityName.nullFlavor = name.@nullFlavor.toString() || '';

	if (!entityName.nullFlavor) {

		delete entityName.nullFlavor;
		entityName.use = name.@use.toString() || '';
		entityName.name = name.toString() || '';	
		entityName.delimiter = name.delimiter.toString() || '';
		entityName.prefix = name.prefix.toString() || '';
		entityName.suffix = name.suffix.toString() || '';			
	}

	return (entityName.nullFlavor || entityName.name) ? entityName : null;
}

/**
	Parse the identifier element that uniquely identifies a thing or object

	@param {Object} identifiers - List of E4X identifier elements 
	@return {Array} return array of identifiers elements
*/

function parseInstanceIdentifier(identifiers) {

	var idList = [];

	for each (var identifier in identifiers) {

		var idPart = {};

		idPart.nullFlavor = identifier.@nullFlavor.toString() || '';

		if (!idPart.nullFlavor) {

			delete idPart.nullFlavor;

			idPart.root = identifier.@root.toString() || '';
			idPart.extension = identifier.@extension.toString() || '';
			idPart.assigningAuthorityName = identifier.@assigningAuthorityName.toString() || '';
			idPart.displayable = identifier.@displayable.toString() || '';			
		}

		idList.push(idPart);
	}

	return idList;

}

/**
	Parse the language communication capabilities of an Entity

	@param {Object} communications - List of E4X LanguageCommunications elements 
	@return {Array} return array of communications elements
*/
function parseCommunication(communications) {

	var languageList = [];

	for each (var language in communications) {

		var communication = {};

		communication.nullFlavor = language.@nullFlavor.toString() || '';

		if (!communication.nullFlavor) {

			delete communication.nullFlavor;

			communication.languageCode = parseCode(language.languageCode);
			communication.modeCode = parseCode(language.modeCode);
			communication.proficiencyLevelCode = parseCode(language.proficiencyLevelCode);
			communication.preferenceInd = language.preferenceInd.@value.toString() || '';	
		}

		languageList.push(communication);	
	}

	return languageList;
}

/**
	Parse a retrievable resource such as a telephone number or e-mail address

	@param {Object} telecoms - List of E4X telecom elements 
	@return {Array} return array of TelecommunicationAddress elements	
*/

function parseTelecom(telecoms) {

	var telList = [];

	for each (var telecom in telecoms) {

		var telPart = {};

		telPart.nullFlavor = telecom.@nullFlavor.toString() || '';

		if (!telPart.nullFlavor) {

			delete telPart.nullFlavor;

			telPart.value = telecom.@value.toString() || '';
			telPart.useablePeriod;
			telPart.use = telecom.@use.toString() || '';			
		}

		telList.push(telPart);
	}

	return telList;	
}

/**
	Parse an element specifying a point on the axis of natural time represented as a calendar expression

	@param {Object} timeStamp - A single E4X time element 
	@return {Object} return PointInTime object
*/
function parsePointInTime(timeStamp) {

	var ts = {};

	ts.nullFlavor = timeStamp.@nullFlavor.toString() || '';

	if (!ts.nullFlavor) {

		delete ts.nullFlavor;

		if (ts.hasOwnProperty('value')) {
			ts.value = timeStamp.@value.toString() || '';
		}			

	}

	return ts;
}


/**
	Parse a set of consecutive values of time-stamps

	@param {Object} interval - List of E4X time elements 
	@return {Object} return TimeInterval object
*/
function parseTimeInterval(interval) {

	var ts = {};

	ts.nullFlavor = interval.@nullFlavor.toString() || '';

	if (!ts.nullFlavor) {

		delete ts.nullFlavor;

		if (ts.hasOwnProperty('value')) {
			ts.value = interval.@value.toString() || '';
		}

		if (ts.hasOwnProperty('low')) {
			ts.low.nullFlavor = interval.low.@nullFlavor.toString() || '';
			if (!ts.low.nullFlavor) {
				delete ts.low.nullFlavor;
				ts.low = interval.low.@value.toString() || '';
			}
		}

		if (ts.hasOwnProperty('high')) {
			ts.high.nullFlavor = interval.high.@nullFlavor.toString() || '';
			if (!ts.high.nullFlavor) {
				delete ts.high.nullFlavor;
				ts.low = interval.high.@value.toString() || '';
			}
		}

		if (ts.hasOwnProperty('width')) {
			ts.width.nullFlavor = interval.width.@nullFlavor.toString() || '';
			if (!ts.width.nullFlavor) {
				delete ts.width.nullFlavor;
				ts.width = interval.width.@value.toString() || '';
			}
		}

		if (ts.hasOwnProperty('center')) {
			ts.center.nullFlavor = interval.center.@nullFlavor.toString() || '';
			if (!ts.center.nullFlavor) {
				delete ts.center.nullFlavor;
				ts.center = interval.center.@value.toString() || '';
			}
		}		
	}

	return ts;
}

/**
	Convert an HL7 to XML.

	@param {String} inORM - the hl7 as string
	@return {XML} return XML (HL7)
*/
function HL7toXML(inORM) {
	//
	//at this point we have a string not HL7 object. 
	//

	//
	//convert PIPE delimited string (HL7 ORM) to XML for easy parsing...
	//
	logger.debug("Converting to XML");
	var ORMtoXML = "";	
	var serializationProperties = SerializerFactory.getDefaultSerializationProperties('HL7V2');
	serializationProperties.put('convertLineBreaks',true);
	serializationProperties.put('useStrictParser',false);
	serializationProperties.put('useStrictValidation',false);
	serializationProperties.put('stripNamespaces',false);
	serializationProperties.put('handleSubcomponents',true);
	serializationProperties.put('handleRepetitions',true);

	// Setting the default namespace is required when using the strict parser
	//default xml namespace = new Namespace('urn:hl7-org:v2xml');

	var ORMtoXML = SerializerFactory.getSerializer('HL7V2', serializationProperties, null).toXML(inORM);  
	var newXML = new XML(ORMtoXML);

	return newXML;
}

