/**
	Set/Assign a Specific Resource and fullURL in a FHIR Bundle.

	@param {JSON}   inFHIR - 
	@param {string} inResourceName - 
	@return {JSON} return updated FHIR Bundle
*/
function SetResourceInBundle(inFHIR, inFHIRResouce, inUUID) {

	//logger.debug("In SetResourceInBundle. Adding" + inFHIRResouce);

	inFHIR.entry[inFHIR.entry.length] 		      = inFHIRResouce;
	inFHIR.entry[inFHIR.entry.length-1].fullUrl   =  inUUID;

	return inFHIR;	
}

/**
	Parse CDA participants defined by AssignedEntity class

	@param {Object} entity - E4X CDA root of AssignedEntity object, e.g., /ClinicalDocument/author
	@return {Object} return HL7 Role class
*/
function getAssignedEntity(entity) {

	var someParticipant = new Role(entity.assignedEntity);
	someParticipant.participation = new Participation(entity);

	if (entity.assignedEntity.hasOwnProperty('assignedPerson')) {
		someParticipant.subject = new Person(entity.assignedEntity.assignedPerson);
	}

	if (entity.assignedEntity.hasOwnProperty('representedOrganization')) {
		someParticipant.scoper = new Organization(entity.assignedEntity.representedOrganization);
	}

	return someParticipant;	
}

/**
	HL7 RIM Entity class
	A physical thing, group of physical things or an organization capable of participating in Acts while in a role.

	@param {Object} person - E4X CDA Person object, e.g., /recordTarget/patientRole/patient
*/
function Entity(person) {

	this.classCode = person.@classCode.toString() || '';
	this.determinerCode = person.@determinerCode.toString() || 'INSTANCE';
	this.id = parseInstanceIdentifier(person.id);
	this.code;
	this.quantity;
	this.name = parseNames(person.name);
	this.desc;
	this.statusCode = parseCode(person.statusCode);
	this.existenceTime;
	this.telecom = parseTelecom(person.telecom);
	this.riskCode;
	this.handlingCode;

	// The language communication capabilities of an Entity
	this.communication = parseCommunication(person.languageCommunication);
}

Entity.prototype.getName = function() {
	return this.name;
}

Entity.prototype.hasCommunication = function() {
	return (this.communication.length > 0);
}

Entity.prototype.getCommunication = function() {
	return this.communication;
}

Entity.prototype.getCommunicationFirstRep = function() {
	return this.communication[0];
}


/**
	LivingSubject class specialization of Entity class
	This class contains administrative attributes of interest to medicine that differentiate living organisms from other Entities

	@param {Object} person - E4X CDA Person object, e.g., /recordTarget/patientRole/patient
*/
function LivingSubject(person) {

	Entity.call(this, person);

	this.administrativeGenderCode = parseCode(person.administrativeGenderCode);
	this.birthTime = person.birthTime.@value.toString() || '';
	this.deceasedInd = false;
	this.deceasedTime = person.deceasedTime.@value.toString() || '';
	this.multipleBirthInd = false;
	this.multipleBirthOrderNumber = person.multipleBirthOrderNumber.@value.toString() || NaN;
	this.organDonorInd = false;
}
// To set LivingSubject as instance of Entity
LivingSubject.prototype = Object.create(Entity.prototype);
LivingSubject.prototype.constructor = LivingSubject;



/**
	Person class specialization of LivingSubject class
	This class can be used to represent either a single individual, a group of individuals or a kind of individual

	@param {Object} person - E4X CDA Person object, e.g., /recordTarget/patientRole/patient
*/
function Person(person) {

	LivingSubject.call(this, person);

	this.classCode = 'PSN';	
	this.addr = parseAddress(person.addr);
	this.maritalStatusCode = parseCode(person.maritalStatusCode);
	this.educationLevelCode = parseCode(person.educationLevelCode);
	this.disabilityCode = parseCode(person.disabilityCode);
	this.religiousAffiliationCode = parseCode(person.religiousAffiliationCode);
	this.raceCode = parseCode(person.raceCode);
	this.ethnicGroupCode = parseCode(person.ethnicGroupCode);
}
// To set Person as instance of LivingSubject
Person.prototype = Object.create(LivingSubject.prototype);
Person.prototype.constructor = Person;


/**
	Place class specialization of Entity class
	A bounded physical place or site, including any contained structures

	@param {Object} place - E4X CDA Place object, e.g., /recordTarget/patientRole/patient/birthplace/place
*/
function Place(place) {

	Entity.call(this, place);

	this.classCode = 'PLC';
	this.mobileInd = place.mobileInd;
	this.addr = parseAddress(place.addr);
	this.directionsText = place.directionsText || '';
	this.positionText = place.positionText || '';

	// Override Entity.name element
	this.name = parseEntityName(place.name);
}
// To set Place as instance of Entity
Place.prototype = Object.create(Entity.prototype);
Place.prototype.constructor = Place;


/**
	Organization class specialization of Entity class
	A bounded physical place or site, including any contained structures

	@param {Object} organization - E4X CDA Organization object, e.g., /recordTarget/patientRole/providerOrganization
*/
function Organization(organization) {

	Entity.call(this, organization);

	this.classCode = 'ORG';
	this.addr = parseAddress(organization.addr);
	this.standardIndustryClassCode = parseCode(organization.standardIndustryClassCode);

	// Override Entity.name element
	this.name = parseEntityName(organization.name);	
}
// To set Organization as instance of Entity
Organization.prototype = Object.create(Entity.prototype);
Organization.prototype.constructor = Organization;

/**
	HL7 RIM Participation class
	An association between an Act and a Role 

	@param {Object} person - E4X CDA Person object, e.g., /recordTarget/patientRole
*/
function Participation(participation) {

	this.typeCode = parseCode(participation.typeCode);
	this.functionCode = parseCode(participation.functionCode);
	this.contextControlCode = parseCode(participation.contextControlCode);
	this.sequenceNumber = participation.sequenceNumber.toString() || '';
	this.priorityNumber = participation.priorityNumber.toString() || '';
	this.negationInd = false;
	this.noteText = participation.noteText.toString() || '';
	this.time = parsePointInTime(participation.time);
	this.modeCode = parseCode(participation.modeCode);
	this.awarenessCode = parseCode(participation.awarenessCode);
	this.signatureCode = parseCode(participation.signatureCode);
	this.signatureText = participation.signatureText.toString() || '';
	this.performInd;
	this.substitutionConditionCode = parseCode(participation.substitutionConditionCode);
	this.subsetCode = parseCode(participation.subsetCode);
	this.quantity;
}

Participation.prototype.setType = function(value) {
	var type = <code code={value} codeSystem="2.16.840.1.113883.5.90"/>;
	this.typeCode = parseCode(type);
}

/**
	HL7 RIM Role class
	A competency of the Entity that plays the Role as identified, defined, guaranteed, or acknowledged by the Entity that scopes the Role

	@param {Object} person - E4X CDA Person object, e.g., /recordTarget/patientRole
*/
function Role(entityRole) {

	this.classCode = entityRole.@classCode.toString() || '';
	this.id = parseInstanceIdentifier(entityRole.id);
	this.code = parseCode(entityRole.code);
	this.negationInd;
	this.name = parseNames(entityRole.name);
	this.addr = parseAddress(entityRole.addr);
	this.telecom = parseTelecom(entityRole.telecom);
	this.statusCode = parseCode(entityRole.statusCode);
	this.effectiveTime = parseTimeInterval(entityRole.effectiveTime);	
	this.certificateText = entityRole.certificateText.toString() || ''
	this.confidentialityCode = parseCode(entityRole.confidentialityCode);
	this.quantity;

	// Reference to Entity that plays this role
	var _subject;
	Object.defineProperty(this, 'subject', {
		set: function(value) {
			this._subject = value;
		}
	});

	// Reference to Entity that scopes this role
	var _scoper;
	Object.defineProperty(this, 'scoper', {
		set: function(value) {
			this._scoper = value;
		}
	});

	// Reference to Participation that associates this Role with the Act
	var _participation;
	Object.defineProperty(this, 'participation', {
		set: function(value) {
			this._participation = value;
		}
	});	
}

Role.prototype.getSubject = function() {
	return this._subject;
}

Role.prototype.getOrganization = function() {
	return this._scoper;
}

Role.prototype.getParticipation = function() {
	return this._participation;
}

Role.prototype.getAddress = function() {
	return this.addr;
}

Role.prototype.getAddressFirstRep = function() {
	return this.addr[0];
}

Role.prototype.getTelecom = function() {
	return this.telecom;
}

Role.prototype.getTelecomFirstRep = function() {
	return this.telecom[0];
}


function Patient(entityRole) {

	Role.call(this, entityRole);

	this.classCode = 'PAT';	
	this.veryImportantPersonCode = parseCode(entityRole.veryImportantPersonCode);

	// Reference to Place entity that plays the role of BirthPlace
	var _birthPlace;
	Object.defineProperty(this, 'birthPlace', {
		set: function(value) {
			this._birthPlace = value;
		}
	});	
}
// To set Patient as instance of Role
Patient.prototype = Object.create(Role.prototype);
Patient.prototype.constructor = Patient;

Role.prototype.getBirthPlace = function() {
	return this._birthPlace;
}
